COUNTED_SAMPLE_VIEW = """
CREATE OR REPLACE VIEW mcri_counted_sample AS
WITH sample_identity AS (
    -- One row per (family, sample_id). seqr_sample has NO unique constraint and carries
    -- dataset_type, so one physical sample yields several rows sharing a sample_id.
    SELECT f.guid                        AS family_guid,
           s.sample_id                   AS sample_id,
           i.id                          AS individual_pk,
           i.guid                        AS individual_guid,
           i.affected                    AS affected,
           s.sample_type                 AS sample_type,
           bool_or(s.is_active)          AS is_active,
           max(s.loaded_date)            AS loaded_date,
           -- The ONLY manual signal. Absence of an exclusion row means counted.
           bool_or(p.is_demo
                OR xp.project_id    IS NOT NULL
                OR xi.individual_id IS NOT NULL) AS is_excluded
      FROM seqr_sample     s
      JOIN seqr_individual i  ON s.individual_id = i.id
      JOIN seqr_family     f  ON i.family_id     = f.id
      JOIN seqr_project    p  ON f.project_id    = p.id
      LEFT JOIN mcri_excluded_count_project    xp ON xp.project_id    = p.id
      LEFT JOIN mcri_excluded_count_individual xi ON xi.individual_id = i.id
     GROUP BY f.guid, s.sample_id, i.id, i.guid, i.affected, s.sample_type
), ranked AS (
    SELECT *,
           -- Preferred sample for this individual WITHIN a sample type.
           -- is_active is a preference, not a filter: an inactive sample with no
           -- replacement still counts.
           row_number() OVER (PARTITION BY individual_pk, sample_type
                              ORDER BY is_active DESC, loaded_date DESC, sample_id) AS rn_type,
           -- Preferred sample for this individual ACROSS sample types (WGS > LRS > WES).
           row_number() OVER (PARTITION BY individual_pk
                              ORDER BY is_active DESC,
                                       CASE sample_type WHEN 'WGS' THEN 1
                                                        WHEN 'LRS' THEN 2
                                                        WHEN 'WES' THEN 3
                                                        ELSE 4 END,
                                       loaded_date DESC, sample_id)                 AS rn_any,
           -- Guarantees exactly one row per dictionary key. COMPLEX_KEY_HASHED treats
           -- duplicate keys as undefined behaviour, so this is required, not defensive.
           row_number() OVER (PARTITION BY family_guid, sample_id
                              ORDER BY is_active DESC, loaded_date DESC)            AS rn_key
      FROM sample_identity
)
-- Every flag is an EXCLUSION signal: 0 means count it. A missing key, a forgotten
-- dictGetOrDefault, or a wrong default all therefore resolve to counting the sample.
SELECT family_guid,
       sample_id,
       individual_guid,
       affected,
       is_excluded::int    AS is_excluded,        -- manual only
       (rn_type != 1)::int AS is_superseded,      -- a preferred sample of this type exists
       (rn_any  != 1)::int AS is_duplicate_assay  -- preferred across types; combined total only
  FROM ranked
 WHERE rn_key = 1;
"""

